depthRows = value or []
depthRow = depthRows[0] if depthRows else {}
depth = depthRow.get("Depth") or 0

cfgRows = BlueRidge.Lots.AimPoolConfig.get() or []
cfg = cfgRows[0] if cfgRows else {}
critDepth = cfg.get("AlarmCriticalDepth")
warnDepth = cfg.get("AlarmWarningDepth")
critAge = cfg.get("PostCriticalAgeMinutes")
warnAge = cfg.get("PostWarningAgeMinutes")

if critDepth is not None and depth <= critDepth:
	depthClass = "pf-kpi-value pf-kpi-value-bad"
elif warnDepth is not None and depth <= warnDepth:
	depthClass = "pf-kpi-value pf-kpi-value-warn"
else:
	depthClass = "pf-kpi-value pf-kpi-value-good"

backlogRows = BlueRidge.Lots.AimPool.listUnposted() or []
backlogCount = len(backlogRows)
if backlogCount:
	oldestAge = backlogRows[0].get("AgeMinutes") or 0
	plural = "" if backlogCount == 1 else "s"
	backlogCaption = "oldest " + str(oldestAge) + " min (" + str(backlogCount) + " row" + plural + ")"
	if critAge is not None and oldestAge >= critAge:
		backlogClass = "pf-kpi-value pf-kpi-value-bad"
	elif warnAge is not None and oldestAge >= warnAge:
		backlogClass = "pf-kpi-value pf-kpi-value-warn"
	else:
		backlogClass = "pf-kpi-value pf-kpi-value-good"
else:
	backlogCaption = "no unposted rows"
	backlogClass = "pf-kpi-value pf-kpi-value-good"

return {
	"depth": depth,
	"depthValueClass": depthClass,
	"backlogCount": backlogCount,
	"backlogCaption": backlogCaption,
	"backlogValueClass": backlogClass
}
